/* hit.js — 赫梯语（Nešili / 𒉈𒅆𒇷，安纳托利亚楔形文字）界面文案翻译表。

  赫梯语（自称 Nešili「涅西里语」，亦名 Hittite）为赫梯帝国的官方语言，属印欧语系
  安纳托利亚语族，以安纳托利亚楔形文字书写，断代约为公元前 1600–1180 年（古赫梯
  王国—新赫梯帝国时期），主要出土于哈图沙（Ḫattuša，今土耳其博阿兹卡莱）等地。
  本表尽力以真实赫梯语词形表达（如 eš- 是、iya- 做、dāi- 放置、parn- 屋、ḫaššu 王、
  šalli- 大、kuit 何、anda 内、namma 且、natta 否、ḫuppar 器皿/容器、ḫašter 星），
  并采用赫梯语特有的苏美尔/阿卡德借字（LUGAL 王、É 屋、DINGIR 神、UD 日、MU 年、
  URU 城、KUR 国）；当代技术名词无从考据者一律音译 + 中文回退，确保每键均有值。
  值格式：本语言书写 (中文原文/拉丁转写)，例如 save: '𒄿𒊭𒀀𒀜𒋻 (保存/išāttar)'。
  每个值的行尾括号注释内含且仅含一个分隔斜杠「/」，斜杠前为中文原文、斜杠后为拉丁
  转写（转写内不得再出现斜杠，中文原文内的斜杠一律写作全角「／」）。
  {单花括号} 插入占位符一律保持原型不变（占位符若自带斜杠，如 {running}/{total}，
  不视为分隔斜杠）。面板「界面设置」里可开关括号注释，也可只显示中文或只显示转写
  （见 store/settings 的 bracketEnabled / bracketLang）。
  appstore.disclaimerText 为具法律效力的中文原文，逐字保留 zh-CN 原样，不译不改。 */
